from pathlib import Path
import re
out=Path(__file__).resolve().parent
def base(name):
 return re.sub(r'^<svg[^>]*>|</svg>\s*$','',(out/(name+'.svg')).read_text())
def wrap(body, transform):
 return f'<g transform="{transform}">{body}</g>'
def ellipse(cx,cy,rx,ry,fill,stroke='#3d623b',width=2.5):
 return f'<ellipse cx="{cx}" cy="{cy}" rx="{rx}" ry="{ry}" fill="{fill}" stroke="{stroke}" stroke-width="{width}"/>'
